// Exact cached DWORD scan in CRT strlen 6EDD80 and raw 23-row diagnostic lookup 6F0B98. Prepared NUL strings include readable aligned tail; no imports or writes.
namespace Recovered.Gameplay {public static class PtlRuntimeStringLength {public static uint Length(SoundSetupImage m,uint pointer){unchecked{uint cursor=pointer;while((cursor&3)!=0){byte value=m.Byte(cursor);cursor++;if(value==0)return cursor-1-pointer;}for(;;){uint value=m.Word(cursor);uint flags=(~value)^(value+0x7efefeff);cursor+=4;if((flags&0x81010100)==0)continue;value=m.Word(cursor-4);if((value&255)==0)return cursor-4-pointer;if((value&0xff00)==0)return cursor-3-pointer;if((value&0xff0000)==0)return cursor-2-pointer;if((value&0xff000000)==0)return cursor-1-pointer;}}}public static uint Message(SoundSetupImage m,uint code){for(uint i=0;i<23;i++)if(m.Word(0x829ac0+i*8)==code)return m.Word(0x829ac4+i*8);return 0;}}}
